        --     else
        --         textBox.Text = v.Char
        --     end
        --     if not lines[v.Line] then
        --         lines[v.Line] = {}
        --     end
        --     for _, c in pairs(lines[v.Line]) do
        --         lineSizeX = lineSizeX + TextService:GetTextSize(c.Char, 14, Enum.Font.Arial, Vector2.new(math.huge, math.huge)).X
